  {q:'选择正确的冠词：___ apple a day.', options:['A','An','The'], answer:1},
  {q:'"He ___ to school yesterday." 正确形式：', options:['go','goes','went'], answer:2},
  {q:'复数形式：child →', options:['childs','children','childes'], answer:1},
  {q:'"She is ___ than me."', options:['tall','taller','tallest'], answer:1},
  {q:'否定句："I ___ like coffee."', options:['do not','does not','am not'], answer:0}
];
function quiz(rng){ return QUIZ[Math.floor(rng()*QUIZ.length)]; }
function check(q, choice){ return q && choice===q.answer; }
var EXPORTS={QUIZ:QUIZ,quiz:quiz,check:check};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GrammarForge2Pure = EXPORTS; }
